def _build_trend_windows(
    events: list[dict],
    window_ms: int,
    tolerate_failures: bool,
) -> list[dict]:
    """按 chain_id 与 finalized_at 所属时间窗口汇总趋势，覆盖整个当前输入。

    window_start_ms 取不大于 finalized_at 的最大 window_ms 整数倍（Python
    地板除对负时间戳同样得到不大于该时刻的起点），按 (chain_id, 起点) 合并；
    没有事件落入的空窗口不输出。行按链在输入中首次出现、链内窗口起点升序。

    每个结构合法事件都计入窗口 event_count 并贡献三段延迟（口径与延迟画像
    一致）。隔离模式（tolerate_failures=True）下证明失败的事件另计
    proof_failure_count 且仍贡献归因与 p95；严格模式分类时遇到证明失败直接
    抛 ProofVerificationError。三个 p95 取最近秩 max(1,ceil(0.95*n))。
    """
    # dict 保留首次插入顺序；窗口键随事件首次出现插入，输出前再按起点排序。
    buckets: dict[tuple[str, int], dict] = {}
    chain_first_seen: dict[str, None] = {}
    for event in events:
        try:
            verify_proof(event)
        except ProofVerificationError:
            if not tolerate_failures:
                raise
            failed = True
        else:
            failed = False

        chain = event["chain_id"]
        chain_first_seen.setdefault(chain, None)
        start = (event["finalized_at"] // window_ms) * window_ms
        key = (chain, start)
        bucket = buckets.get(key)
        if bucket is None:
            bucket = {
                "event_count": 0,
                "proof_failure_count": 0,
                "attribution_counts": {
                    name: 0 for name in ATTRIBUTION_FIELDS
                },
                **{name: [] for name in LATENCY_THRESHOLD_FIELDS},
            }
            buckets[key] = bucket
        bucket["event_count"] += 1
        if failed:
            bucket["proof_failure_count"] += 1
        latency = _latency_fields(event)
        bucket["attribution_counts"][latency["attribution"]] += 1
        for name in LATENCY_THRESHOLD_FIELDS:
            bucket[name].append(latency[name])

    rows: list[dict] = []
    for chain in chain_first_seen:
        starts = sorted(start for cid, start in buckets if cid == chain)
        for start in starts:
            bucket = buckets[(chain, start)]
            rows.append(
                {
                    "chain_id": chain,
                    "window_start_ms": start,
                    "event_count": bucket["event_count"],
                    "proof_failure_count": bucket["proof_failure_count"],
                    "attribution_counts": dict(bucket["attribution_counts"]),
                    "latency_p95_ms": {
                        name: _nearest_rank(sorted(bucket[name]), 0.95)
                        for name in LATENCY_THRESHOLD_FIELDS
                    },
                }
            )
    return rows


